//! Differential AC (card 5.M1): parse the canonical SRT sample set
//! generated by **ffmpeg 7.1.5** (`-c:s srt`) from known-cue
//! WebVTT inputs — cue counts, times (µs) and text must equal the
//! input truth, tag-for-tag.
//!
//! Fixtures (committed, `tests/fixtures/canonical/`):
//!
//! | file | generated by | truth |
//! |---|---|---|
//! | `out1.srt` | `ffmpeg -i truth1.vtt -c:s srt` | 2 cues, `<b>/<i>` + `<u>` styling survives |
//! | `out2.srt` | `ffmpeg -i truth2.vtt -c:s srt` | 3 plain cues, exact times |
//! | `out3.srt` | `ffmpeg -i truth3.vtt -c:s srt` | 3 cues incl. 0-duration-adjacent, multiline, 24 h+ hour |
//! | `out2-utf16le.srt` | `iconv` of out2 (BOM'd UTF-16LE) | identical to out2 |
//! | `out3-utf16be.srt` | `iconv` of out3 (BOM'd UTF-16BE) | identical to out3 |
//!
//! The truth tables below are hand-derived from the *inputs* (the
//! VTT cue lists), not from this parser's output — no echo chamber
//! (D-9).

use subtitles::model::cue::{CueText, StyledSegment};
use subtitles::model::style::{Color, TextStyle};
use subtitles::srt::{self, SourceEncoding, SrtDocument};
use testkit::Must;

const CANONICAL: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/canonical");

fn parse_file(name: &str) -> SrtDocument {
    let bytes = std::fs::read(format!("{CANONICAL}/{name}")).must();
    srt::parse(&bytes)
}

fn plain(id: u64, start_us: i64, end_us: i64, text: &str, doc: &SrtDocument, i: usize) {
    let cue = &doc.cues[i];
    assert_eq!(cue.id.get(), id, "cue {i} id");
    assert_eq!(cue.interval.start_us(), start_us, "cue {i} start");
    assert_eq!(cue.interval.end_us(), end_us, "cue {i} end");
    assert_eq!(cue.text, CueText::Plain(text.to_owned()), "cue {i} text");
    assert!(doc.is_clean(), "unexpected damage: {:?}", doc.damages);
}

#[test]
fn canonical_out1_styled_tags_survive() {
    let doc = parse_file("out1.srt");
    assert_eq!(doc.encoding, SourceEncoding::Utf8);
    assert_eq!(doc.cues.len(), 2);
    assert!(doc.is_clean());
    let cue = &doc.cues[0];
    assert_eq!(cue.id.get(), 1);
    assert_eq!(cue.interval.start_us(), 2_000_000);
    assert_eq!(cue.interval.end_us(), 5_000_000);
    // ffmpeg keeps <b>/<i> tags through the VTT→SRT hop.
    assert_eq!(
        cue.text,
        CueText::Styled(vec![
            StyledSegment {
                text: "Bold".into(),
                style: TextStyle::new(true, false, false, None)
            },
            StyledSegment {
                text: " and ".into(),
                style: TextStyle::PLAIN
            },
            StyledSegment {
                text: "italic".into(),
                style: TextStyle::new(false, true, false, None)
            },
            StyledSegment {
                text: " mix".into(),
                style: TextStyle::PLAIN
            },
        ])
    );
    let cue = &doc.cues[1];
    assert_eq!(cue.id.get(), 2);
    assert_eq!(cue.interval.start_us(), 6_000_000);
    assert_eq!(cue.interval.end_us(), 8_000_000);
    // ffmpeg DROPPED the <font color="#00ff00"> wrapper (kept the
    // text) — the parser must match that reality: plain " green".
    assert_eq!(
        cue.text,
        CueText::Styled(vec![
            StyledSegment {
                text: "Underlined".into(),
                style: TextStyle::new(false, false, true, None)
            },
            StyledSegment {
                text: " green".into(),
                style: TextStyle::PLAIN
            },
        ])
    );
}

#[test]
fn canonical_out2_exact_times_and_text() {
    let doc = parse_file("out2.srt");
    assert_eq!(doc.cues.len(), 3);
    plain(1, 1_000_000, 4_000_000, "Hello world", &doc, 0);
    plain(2, 5_500_000, 9_250_000, "Second line here", &doc, 1);
    plain(3, 62_030_000, 62_050_000, "Quick flash cue", &doc, 2);
}

#[test]
fn canonical_out3_edges_multiline_and_hour_rollover() {
    let doc = parse_file("out3.srt");
    assert_eq!(doc.cues.len(), 3);
    plain(1, 0, 1_000, "A", &doc, 0);
    plain(2, 600_000_000, 683_456_000, "Line one\nLine two", &doc, 1);
    // 23:59:59,900 → 24:00:00,100: the 24 h+ hour survives.
    plain(
        3,
        86_399_900_000,
        86_400_100_000,
        "Past midnight hour rollover",
        &doc,
        2,
    );
}

#[test]
fn canonical_utf16_variants_parse_identically() {
    let le = parse_file("out2-utf16le.srt");
    assert_eq!(le.encoding, SourceEncoding::Utf16Le);
    assert_eq!(le.cues.len(), 3);
    plain(1, 1_000_000, 4_000_000, "Hello world", &le, 0);
    plain(2, 5_500_000, 9_250_000, "Second line here", &le, 1);
    plain(3, 62_030_000, 62_050_000, "Quick flash cue", &le, 2);

    let be = parse_file("out3-utf16be.srt");
    assert_eq!(be.encoding, SourceEncoding::Utf16Be);
    assert_eq!(be.cues.len(), 3);
    plain(1, 0, 1_000, "A", &be, 0);
    plain(2, 600_000_000, 683_456_000, "Line one\nLine two", &be, 1);
    plain(
        3,
        86_399_900_000,
        86_400_100_000,
        "Past midnight hour rollover",
        &be,
        2,
    );
}

#[test]
fn render_path_over_canonical_cues() {
    // The render path must place every canonical cue on a 1080p
    // extent (geometry only — fonts are the renderer's).
    for name in ["out1.srt", "out2.srt", "out3.srt"] {
        let doc = parse_file(name);
        for cue in &doc.cues {
            let rect = subtitles::srt::place_plain_text(
                cue,
                &subtitles::srt::TextMetrics::default(),
                (1920, 1080),
            )
            .must();
            assert!(rect.width > 0 && rect.height > 0);
            assert!(rect.x <= 1920 && rect.y <= 1080);
        }
    }
}

#[test]
fn styled_segment_colors_parse_when_authored() {
    // ffmpeg drops <font color>; authored input keeps it — pin the
    // color mapping through a hand-written sample (subset of the
    // tags unit matrix, exercised at the document level).
    let doc =
        srt::parse(b"1\n00:00:01,000 --> 00:00:02,000\n<font color=\"#00ff00\">green</font>\n");
    assert!(doc.is_clean());
    assert_eq!(
        doc.cues[0].text,
        CueText::Styled(vec![StyledSegment {
            text: "green".into(),
            style: TextStyle::new(false, false, false, Some(Color::new(0, 255, 0, 255)))
        }])
    );
}
